import{j as e,b as i}from"./index-Q5tmBBoz.js";import{I as s}from"./InfoPage-CouG5ON_.js";import"./PageHeader-D19aNveu.js";function n(){return e.jsx(s,{title:"Libraries and collections",lead:"The Gibson Library is the working heart of academic life at Brightwell — nearly thirteen million printed and digital items, open to students, staff and, by arrangement, the public.",crumbs:[{to:"/",label:"Home"},{to:"/about",label:"About"},{label:"Libraries"}],sections:[{heading:"A library for every discipline",body:["The central Gibson Library holds the University’s main reading rooms, the legal deposit collections and the West African heritage archives. Around it sit more than thirty subject and college libraries, each with its own specialist staff.","Most reading rooms are open seven days a week during term, with 24-hour access for students in the Gibson and Medical Sciences libraries during examinations."],aside:{title:"The Gibson Library",rows:[["Printed items","13 million"],["Subject libraries","34"],["Study spaces","7,800"],["Open hours","24/7 in term"],["Members","52,000 active"]],links:[["/visitors","Visiting the University"]]}},{heading:"Collections that belong to the world",intro:"Our special collections preserve stories that reach across continents and centuries.",body:["The manuscripts digitised by the Ogun project — many photographed for the first time — join a growing open digital library. Rare maps, early scientific instruments and the papers of generations of Brightwell scholars are catalogued and conserved by professional staff."],list:{title:"Reader services we offer",items:["Research consultations and inductions for new students.","A digitisation service for personal scholarship and public projects.","Teaching rooms inside the collections for seminars and object sessions.","Inter-library loans and document supply for researchers worldwide."]}},{heading:"For researchers and the public",body:["Members of the public may consult the Gibson Library’s open collections with a visitor ticket, available at the enquiry desk. Researchers planning sustained access should request a reader card in advance.","During vacations the main reading rooms host exhibitions drawn from the special collections — entry is free and no booking is needed for the permanent displays."],aside:{title:"Plan your visit",rows:[["Address","Gibson Library, Brightwell Campus"],["Enquiry desk",`${i.phone}`],["Email","libraries@brightwell.ng"],["Admission","Free visitor ticket"]],links:[["/museums","Museums and collections"],["/map","Map and travel"]]}}]})}export{n as default};
